            <?php foreach ($list['items'] as $row): ?><tr data-tour-row="<?= (int) $row['id_tour'] ?>"><td><div class="admin-tour-cell"><img src="<?= $escape($imageUrl($row['duong_dan_anh'])) ?>" alt="" loading="lazy"><div><a href="<?= $escape($toursUrl(['view' => $row['id_tour']])) ?>"><?= $escape($row['ten_tour']) ?></a><small><?= $escape($row['ma_tour']) ?><?= (int) $row['noi_bat'] ? ' · Nổi bật' : '' ?></small></div></div></td><td><?= $escape($row['ten_diem_den']) ?><small class="admin-category-code"><?= $types[$row['loai_tour']] ?><?= !(int) $row['diem_den_hoat_dong'] ? ' · Điểm đến ngừng hoạt động' : '' ?></small></td><td><?= (int) $row['so_ngay'] ?> ngày</td><td><?= $row['next_departure'] ? date('d/m/Y', strtotime($row['next_departure'])) : 'Chưa có lịch mở' ?><small class="admin-category-code"><?= (int) $row['schedule_count'] ?> lịch · <?= (int) $row['order_count'] ?> đơn</small></td><td><span class="admin-tour-status is-<?= $row['trang_thai'] ?>"><?= $statuses[$row['trang_thai']] ?></span></td><td><div class="admin-row-actions"><a class="admin-row-button" href="<?= $escape($toursUrl(['edit' => $row['id_tour']])) ?>" aria-label="Sửa <?= $escape($row['ten_tour']) ?>"><svg class="icon" aria-hidden="true"><use href="#a-edit"/></svg><span>Sửa</span></a><a class="admin-row-button is-delete" href="<?= $escape($toursUrl(['delete' => $row['id_tour']])) ?>#tour-delete" aria-label="Xóa <?= $escape($row['ten_tour']) ?>"><svg class="icon" aria-hidden="true"><use href="#a-trash"/></svg></a></div></td></tr><?php endforeach; ?>
            <?php if (!$list['items']): ?><tr><td colspan="6" class="admin-empty"><strong>Chưa có tour phù hợp</strong><p>Thay đổi bộ lọc hoặc thêm tour mới để bắt đầu.</p></td></tr><?php endif; ?>
        </tbody></table></div>
        <div class="admin-accounts-list-footer"><p>Hiển thị <?= $list['total'] ? ($list['page'] - 1) * 10 + 1 : 0 ?>–<?= min($list['page'] * 10, $list['total']) ?> / <?= $list['total'] ?> tour</p><?php if ($list['pages'] > 1): ?><nav class="admin-accounts-pagination" aria-label="Phân trang tour"><?php if ($list['page'] > 1): ?><a href="<?= $escape($toursUrl(['p' => $list['page'] - 1])) ?>" aria-label="Trang trước">‹</a><?php endif; ?><?php $links = array_unique(array_merge([1], range(max(1, $list['page'] - 2), min($list['pages'], $list['page'] + 2)), [$list['pages']])); sort($links); $previous = 0; foreach ($links as $number): ?><?php if ($previous && $number > $previous + 1): ?><span aria-hidden="true">…</span><?php endif; ?><a href="<?= $escape($toursUrl(['p' => $number])) ?>" <?= $list['page'] === $number ? 'aria-current="page"' : '' ?>><?= $number ?></a><?php $previous = $number; endforeach; ?><?php if ($list['page'] < $list['pages']): ?><a href="<?= $escape($toursUrl(['p' => $list['page'] + 1])) ?>" aria-label="Trang tiếp theo">›</a><?php endif; ?></nav><?php endif; ?></div>
    </section>
    <?php endif; ?>
</div>
